function triangularSum(nums) {
  let length = nums.length;
  while (length > 1) {
    for (let i = 0; i + 1 < length; i++) {
      const pairSum = nums[i] + nums[i + 1];
      nums[i] = pairSum % 10;
    }
    length--;
  }
  return nums[0];
}

