function triangularSum(nums) {
  // Each value reaches the top weighted by a binomial coefficient of Pascal's triangle.
  const n = nums.length;
  let total = 0n;
  let coefficient = 1n;
  for (let k = 0; k < n; k++) {
    total += coefficient * BigInt(nums[k]);
    coefficient = coefficient * BigInt(n - 1 - k) / BigInt(k + 1);
  }
  return Number(total % 10n);
}

