function generate(rand, size) {
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 9);
  const mode = Math.floor(rand() * 4);
  const nums = Array.from({ length: n }, () => {
    if (mode === 0) return Math.floor(rand() * 10);
    if (mode === 1) return rand() < 0.5 ? 9 : 0;
    if (mode === 2) return 5 + Math.floor(rand() * 5);
    return rand() < 0.2 ? Math.floor(rand() * 10) : 0;
  });
  return [nums];
}
